        .wrapper{max-width:600px;margin:auto;padding:40px;background:#fff;border-radius:6px;box-shadow:0 2px 8px rgba(0,0,0,0.1);margin-top:30px;}
        h1{font-size:2em;margin-bottom:20px;text-align:center;}
        form{display:flex;flex-direction:column;}
        label{margin-top:15px;font-weight:bold;}
        input, select, textarea{margin-top:5px;padding:10px;border:1px solid #ccc;border-radius:4px;font-size:1em;width:100%;box-sizing:border-box;}
        textarea{resize:vertical;height:100px;}
        .btn{margin-top:25px;background:#ff6600;color:#fff;padding:12px;border:none;border-radius:4px;font-size:1.1em;cursor:pointer;}
        .btn:hover{background:#e65c00;}
        .message{margin-top:15px;color:#d00;display:none;}
        .footer{background:#333;color:#ccc;padding:30px 40px;text-align:center;font-size:0.9em;margin-top:60px;}
